141:     : '';
142:   const time = city.time != null ? `<span class="wc-time">${esc(city.time)}</span>` : '';
143: 
144:   const header = `<div class="wc-header"><div class="wc-location"><span class="wc-city">${esc(city.city)}</span>${sub}</div>${time}</div>`;
