146:   const main = `<div class="wc-main"><span class="wc-icon" aria-hidden="true">${cond.emoji}</span><div class="wc-temp"><span class="wc-temp-value">${esc(city.temp ?? '–')}</span><span class="wc-temp-unit">${unit}</span></div><p class="wc-condition">${label}</p></div>`;
147: 
148:   const stats = statRows(city);
149:   const hourlyHtml = hourlyRow(city.hourly, unit);
