151:   return `<article class="wc" style="--wc-bg:${gradient}; --wc-text:${theme.text}; --wc-chip:${theme.chip}">${header}${main}${stats ? `<div class="wc-stats">${stats}</div>` : ''}${hourlyHtml}</article>`;
